/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 숨기기
        label_156.hide();
        label_157.hide();
        ck_int_rt_chg_seq.hide();
        ck_int_rt_chg_dd.hide();
        $c.bns.BnsPanelToGroupBox(pnl_main); // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_leftSch); // 패널라운드처리
        // BnsPanelToGroupBox(panel_1);        //패널라운드처리
        $c.bns.BnsPanelToGroupBox(panel_2_bas); // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(panel_5); // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(panel_2); // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(panel_7); // 패널라운드처리

        // 콤보설정
        scwin.setComboCode();
        tab_Main.setSelectedTabIndex(1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25200.onpageload" });
    }
};

