        ck_ass_liq_cd.setValue(flag);
        ck_pre_af_cd.setValue(flag);
        ck_lst_dt.setValue(flag);
        ck_iss_dt.setValue(flag);
        ck_rdmp_dt.setValue(flag);
        ck_sale_dt.setValue(flag);
        ck_fst_int_dt.setValue(flag);
