/**
 * @method
 * @name grd_List1_OnDblClick
 * @description grd_List1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List1_OnDblClick = function(row, colid) {
    try {
        if (dts_List1.getRowCount() === 0) return;
        if (row > 0) {
            scwin.vgStdCd = dts_List1.getCellData(row, "STD_CD");
            scwin.fn_GetPar = scwin.getParIsuDtlAndMktactDtl;
            $c.bns.fn_PopIsuDtlAndMktactDtl(grd_List1);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25200.grd_List1_OnDblClick" });
    }
};

