    param += "&{P}V_WV_INST_CD=" + txb_Inst_cd.getValue();
    param += "&{P}V_WV_BND_KIND=" + cmb_bnd_kind.getValue();
    param += "&{P}V_WV_BND_TYP_CD=" + txb_bnd_typ_cd.getValue();
    param += "&{P}V_WV_LST_YN=" + cmb_lst_yn.getValue();
    param += "&{P}V_WV_DLST_RSN=" + txb_dlst_rsn.getValue();
    param += "&{P}V_WV_GRT_CD=" + cmb_grt_cd.getValue();
    param += "&{P}V_WV_NUSUAL_BND_TP_CD=" + cmb_nusual_bnd_tp_cd.getValue();
