    param += "&{P}V_WV_PRE_AF_CD=" + cmb_pre_af_cd.getValue();
    // param += "&{P}V_WV_ISS_PR="+ txb_iss_pr.value;
    param += "&{P}V_WV_ISS_PR=" + edt_iss_pr.getValue();
    param += "&{P}V_WV_RGHT_TP_CD=" + cmb_rght_tp_cd.getValue();
    // param += "&{P}V_WV_REG_AGT="+ txb_reg_agt.value;
