    param += "&{P}V_WV_MAIN_CO=" + txb_main_co.getValue();
    param += "&{P}V_WV_TRST_INST=" + txb_trst_inst.getValue();
    param += "&{P}V_WV_CRDT_INST=" + cmb_crdt_inst.getValue();
    param += "&{P}V_WV_CRDT_INST_GRAD=" + cmb_crdt_inst_grad.getValue();
