    param += "&{P}V_WV_ISS_STRT_DD=" + edt_iss_strt_dd.getValue();
    param += "&{P}V_WV_RDMP_STRT_DD=" + edt_rdmp_strt_dd.getValue();
    param += "&{P}V_WV_LST_STRT_DD=" + edt_lst_strt_dd.getValue();
