/**
 * @method
 * @name btnExcel
 * @description 엑셀작업
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btnExcel = async function() {
    let voDtsList;
    let vsTabSel = tab_Main.getSelectedTabIndex();
    if (vsTabSel === 3) {
        voDtsList = dts_List2;
    } else {
        voDtsList = dts_List1;
    }
    if (voDtsList.getRowCount() > 0) {
        const today = $c.ut.cGetToday("yyyymmddhhmmss");
        if (vsTabSel === 3) {
            // 파일형식 today_화면명.xls
            let xls_path = $c.session.getExcelDownPath() + "상장채권(상장기준)_" + today + ".xlsx";
            $c.data.downloadGridViewOffice(grd_List2, "sheet1", xls_path, 8, 0);
        } else {
            // 파일형식 today_화면명.xls
            let xls_path = $c.session.getExcelDownPath() + "상장채권(전체)_" + today + ".xlsx";
            $c.data.downloadGridViewOffice(grd_List1, "sheet1", xls_path, 8, 0);
            // grd_List1.SaveExcel('', false, false, true, fileNm);
            // grd_List1.GridToExcel('', "", 8);

        }
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

