    $c.bns.fn_SetBnsCombo("ULDBNS25200.xml", dts_CREDIT_GRD_CD, '02209'); // 신용평가등급
    if (dts_CREDIT_GRD_CD.getCellData(1, "VALUE") === "") {
        dts_CREDIT_GRD_CD.setCellData(1, "VALUE", "ALL");
        dts_CREDIT_GRD_CD.setCellData(1, "TEXT", "ALL");
        cmb_crdt_inst_grad.setSelectedIndex(0);
    }
    dts_CREDIT_GRD_CD.setBroadcast(false);
    for (j = 1; j <= dts_CREDIT_GRD_CD.getRowCount(); j++) {
        if (j > 1) {
            dts_CREDIT_GRD_CD.setCellData(j, "TEXT", dts_CREDIT_GRD_CD.getCellData(j, "VALUE"));
        }
    }
    dts_CREDIT_GRD_CD.setBroadcast(true, true);
};
